-- Stage 5: suporte, notificações persistentes e resumo financeiro administrativo
create table if not exists public.support_tickets(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id) on delete restrict,subject text not null,message text not null,status text not null default 'open' check(status in ('open','in_progress','resolved')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.support_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete restrict,message text not null,created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles(id) on delete cascade,type text not null,title text not null,message text not null,related_type text,related_id uuid,dedupe_key text not null unique,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists support_tickets_seller_idx on public.support_tickets(seller_id,created_at desc);
create index if not exists support_messages_ticket_idx on public.support_messages(ticket_id,created_at);
create index if not exists notifications_recipient_idx on public.notifications(recipient_id,read_at,created_at desc);
alter table public.support_tickets enable row level security; alter table public.support_messages enable row level security; alter table public.notifications enable row level security;
drop policy if exists "support tickets own or admin" on public.support_tickets; create policy "support tickets own or admin" on public.support_tickets for select to authenticated using(seller_id=auth.uid() or public.is_admin());
drop policy if exists "support messages own ticket or admin" on public.support_messages; create policy "support messages own ticket or admin" on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and (t.seller_id=auth.uid() or public.is_admin())));
drop policy if exists "notifications own" on public.notifications; create policy "notifications own" on public.notifications for select to authenticated using(recipient_id=auth.uid());
revoke insert,update,delete on public.support_tickets,public.support_messages,public.notifications from authenticated; grant select on public.support_tickets,public.support_messages,public.notifications to authenticated;
create or replace function public.create_support_ticket(p_subject text,p_message text) returns public.support_tickets language plpgsql security definer set search_path='' as $$ declare r public.support_tickets; begin if not exists(select 1 from public.profiles where id=auth.uid() and role='seller' and status='active') then raise exception 'Conta de vendedor indisponível'; end if; if length(trim(coalesce(p_subject,'')))<3 or length(trim(coalesce(p_subject,'')))>160 then raise exception 'Assunto inválido'; end if; if length(trim(coalesce(p_message,'')))<3 then raise exception 'Mensagem inválida'; end if; insert into public.support_tickets(seller_id,subject,message) values(auth.uid(),trim(p_subject),trim(p_message)) returning * into r; insert into public.audit_logs(actor_id,target_user_id,action,metadata) values(auth.uid(),auth.uid(),'support.ticket_created',jsonb_build_object('ticket_id',r.id)); return r; end $$;
create or replace function public.admin_reply_support(p_ticket_id uuid,p_message text,p_status text default 'in_progress') returns public.support_messages language plpgsql security definer set search_path='' as $$ declare r public.support_messages; begin if not public.is_admin() then raise exception 'Acesso negado'; end if; if p_status not in ('in_progress','resolved') then raise exception 'Estado inválido'; end if; if length(trim(coalesce(p_message,'')))<1 then raise exception 'Mensagem obrigatória'; end if; if not exists(select 1 from public.support_tickets where id=p_ticket_id) then raise exception 'Chamado não encontrado'; end if; insert into public.support_messages(ticket_id,author_id,message) values(p_ticket_id,auth.uid(),trim(p_message)) returning * into r; update public.support_tickets set status=p_status,updated_at=now(),resolved_at=case when p_status='resolved' then now() else null end where id=p_ticket_id; insert into public.audit_logs(actor_id,action,metadata) values(auth.uid(),'support.replied',jsonb_build_object('ticket_id',p_ticket_id,'status',p_status)); return r; end $$;
create or replace function public.mark_notification_read(p_notification_id uuid) returns public.notifications language sql security definer set search_path='' as $$ update public.notifications set read_at=coalesce(read_at,now()) where id=p_notification_id and recipient_id=auth.uid() returning * $$;
create or replace function public.admin_financial_summary(p_start timestamptz default null,p_end timestamptz default null,p_seller_id uuid default null) returns table(active_sellers bigint,suspended_sellers bigint,pending_payments_eur numeric,under_review_payments_eur numeric,approved_gross_eur numeric,jaguapay_sales_fees_eur numeric,withdrawal_fees_paid_eur numeric,sellers_available_eur numeric,sellers_reserved_eur numeric,withdrawals_awaiting_action bigint,withdrawals_paid bigint) language sql security definer set search_path='' as $$ select (select count(*) from public.profiles p where p.role='seller' and p.status='active'),(select count(*) from public.profiles p where p.role='seller' and p.status='suspended'),coalesce((select sum(p.gross_amount_eur) from public.payment_records p where p.status='pending' and (p_start is null or p.created_at>=p_start) and (p_end is null or p.created_at<p_end) and (p_seller_id is null or p.seller_id=p_seller_id)),0),coalesce((select sum(p.gross_amount_eur) from public.payment_records p where p.status='under_review' and (p_start is null or p.created_at>=p_start) and (p_end is null or p.created_at<p_end) and (p_seller_id is null or p.seller_id=p_seller_id)),0),coalesce((select sum(p.gross_amount_eur) from public.payment_records p where p.status='approved' and (p_start is null or p.created_at>=p_start) and (p_end is null or p.created_at<p_end) and (p_seller_id is null or p.seller_id=p_seller_id)),0),coalesce((select sum(p.fee_amount_eur) from public.payment_records p where p.status='approved' and (p_start is null or p.created_at>=p_start) and (p_end is null or p.created_at<p_end) and (p_seller_id is null or p.seller_id=p_seller_id)),0),coalesce((select sum(w.fixed_fee_snapshot_eur) from public.withdrawals w where w.status='paid' and (p_start is null or w.paid_at>=p_start) and (p_end is null or w.paid_at<p_end) and (p_seller_id is null or w.seller_id=p_seller_id)),0),coalesce((select sum(l.amount_eur) from public.payment_financial_ledger l where l.entry_type in ('sale_credit','reversal_debit') and (p_seller_id is null or l.seller_id=p_seller_id)),0),coalesce((select sum(w.amount_eur) from public.withdrawals w where w.status in ('requested','under_review','approved_for_payment','processing') and (p_seller_id is null or w.seller_id=p_seller_id)),0),(select count(*) from public.withdrawals w where w.status in ('requested','under_review','approved_for_payment','processing') and (p_seller_id is null or w.seller_id=p_seller_id)),(select count(*) from public.withdrawals w where w.status='paid' and (p_start is null or w.paid_at>=p_start) and (p_end is null or w.paid_at<p_end) and (p_seller_id is null or w.seller_id=p_seller_id)) where public.is_admin() $$;
revoke all on function public.admin_financial_summary(timestamptz,timestamptz,uuid) from public,anon; grant execute on function public.admin_financial_summary(timestamptz,timestamptz,uuid) to authenticated;
create or replace function public.emit_notification(p_recipient uuid,p_type text,p_title text,p_message text,p_related_type text,p_related_id uuid,p_dedupe_key text) returns void language plpgsql security definer set search_path='' as $$ begin insert into public.notifications(recipient_id,type,title,message,related_type,related_id,dedupe_key) values(p_recipient,p_type,p_title,p_message,p_related_type,p_related_id,p_dedupe_key) on conflict(dedupe_key) do nothing; exception when others then null; end $$;
create or replace function public.notify_payment_event() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then perform public.emit_notification(new.seller_id,'payment','Pagamento enviado','Seu pagamento foi recebido e aguarda conferência.','payment',new.id,'payment:submitted:'||new.id); perform public.emit_notification(p.id,'payment','Novo pagamento para análise','Há um novo pagamento aguardando conferência.','payment',new.id,'payment:admin:'||new.id) from public.profiles p where p.role='admin' and p.status='active'; elsif new.status is distinct from old.status and new.status in ('approved','rejected','under_review','estornado') then perform public.emit_notification(new.seller_id,'payment','Atualização de pagamento','O pagamento '||new.payment_code||' foi atualizado para '||new.status||'.','payment',new.id,'payment:status:'||new.id||':'||new.status); end if; return new; exception when others then return new; end $$;
drop trigger if exists trg_notify_payment on public.payment_records; create trigger trg_notify_payment after insert or update of status on public.payment_records for each row execute function public.notify_payment_event();
create or replace function public.notify_withdrawal_event() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then perform public.emit_notification(p.id,'withdrawal','Novo saque','Há uma nova solicitação de saque aguardando ação.','withdrawal',new.id,'withdrawal:admin:'||new.id) from public.profiles p where p.role='admin' and p.status='active'; elsif new.status is distinct from old.status then perform public.emit_notification(new.seller_id,'withdrawal','Atualização de saque','Seu saque foi atualizado para '||new.status||'.','withdrawal',new.id,'withdrawal:status:'||new.id||':'||new.status); end if; return new; exception when others then return new; end $$;
drop trigger if exists trg_notify_withdrawal on public.withdrawals; create trigger trg_notify_withdrawal after insert or update of status on public.withdrawals for each row execute function public.notify_withdrawal_event();
create or replace function public.notify_support_ticket() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then perform public.emit_notification(p.id,'support','Novo chamado','Há um novo chamado de suporte.','support',new.id,'support:admin:'||new.id) from public.profiles p where p.role='admin' and p.status='active'; elsif tg_op='UPDATE' and new.updated_at is distinct from old.updated_at then perform public.emit_notification(new.seller_id,'support','Resposta do suporte','Seu chamado "'||new.subject||'" recebeu uma atualização.','support',new.id,'support:update:'||new.id||':'||md5(new.subject||':'||new.status||':'||coalesce((select sm.message from public.support_messages sm where sm.ticket_id=new.id order by sm.created_at desc limit 1),''))); end if; return new; exception when others then return new; end $$;
drop trigger if exists trg_notify_support on public.support_tickets; create trigger trg_notify_support after insert or update on public.support_tickets for each row execute function public.notify_support_ticket();
revoke all on function public.create_support_ticket(text,text) from public,anon; grant execute on function public.create_support_ticket(text,text) to authenticated;
revoke all on function public.admin_reply_support(uuid,text,text) from public,anon; grant execute on function public.admin_reply_support(uuid,text,text) to authenticated;
revoke all on function public.mark_notification_read(uuid) from public,anon; grant execute on function public.mark_notification_read(uuid) to authenticated;